const Redlock = require('redlock');
const Redis = require('ioredis');

const clients = [
  new Redis({ host: 'redis1.local', port: 6379 }),
  new Redis({ host: 'redis2.local', port: 6379 }),
  new Redis({ host: 'redis3.local', port: 6379 })
];

const redlock = new Redlock(clients, {
  driftFactor: 0.01,
  retryCount: 3,
  retryDelay: 200,
});

async function processOrder(orderId) {
  let lock;
  try {
    lock = await redlock.acquire([`locks:order:${orderId}`], 5000);
    // Critical section
    console.log(`Processing order ${orderId}`);
  } catch (error) {
    console.error('Failed to acquire lock', error);
  } finally {
    if (lock) {
      await lock.release();
    }
  }
}
