Appending an event to an EventStoreDB stream with optimistic concurrency control

```typescript
import { jsonEvent, EventStoreDBClient } from '@eventstore/db-client';

const client = EventStoreDBClient.connection('esdb://localhost:2113?tls=false');

async function handleDeposit(accountId: string, amount: number, expectedVersion: bigint) {
  const event = jsonEvent({
    type: 'MoneyDeposited',
    data: { accountId, amount, timestamp: new Date().toISOString() }
  });

  await client.appendToStream(`account-${accountId}`, event, {
    expectedRevision: expectedVersion
  });
}
```

